    "actions": [{"num": "01", "h4": "今天动手做一件你一直在'研究'的事", "p": "哪怕很糙，先做出来。", "tag": ""}, {"num": "02", "h4": "把'会社 / 团队'重新定义成'做事的场'", "p": "砍掉形式主义会议与花架子。", "tag": ""}, {"num": "03", "h4": "给年轻人一个'可以搞砸'的小项目", "p": "为安全失败留额度。", "tag": ""}, {"num": "04", "h4": "用'我亲手做过吗'检验一个判断", "p": "别只靠听汇报拍板。", "tag": ""}, {"num": "05", "h4": "别用头衔评价人，用作品", "p": "把'X 总'换成'做过什么'。", "tag": ""}, {"num": "06", "h4": "去现场找那个你 PPT 里找不到的答案", "p": "卡住的问题，答案在现场。", "tag": ""}, {"num": "07", "h4": "承认一次失败，并把它写成勋章", "p": "敢承认，才敢再动。", "tag": ""}, {"num": "08", "h4": "保留一点不肯安分的劲儿", "p": "做一件'别人说你不该再做'的倔强事。", "tag": ""}],
