    "lede": "八十多年的人生与两家世界 500 强之后，稻盛把一切归结到一个字——'心'。这本《心法》（又作《心》），是他晚年最凝练的总结：人生的结果，终归由你的心相决定。",
    "byline": [["作者", "稻盛和夫（1932—2022）"], ["首版", "2019（87 岁收官）"], ["身份", "京瓷 · KDDI 创始人"]],
    "infoHead": {"num": "01 /", "eyebrow": "关于这本书", "h2": "人生的一切，<br/>都是自己<b class=\"tail\">内心的投射</b>", "sub": "《心》（中文常译《心法》）是稻盛和夫 2019 年的收官之作，时年 87 岁。他把毕生经营与人生智慧浓缩为一句话：'人生的一切，都是自己内心的投射。' 从'利他之心''感恩之心''反省之心'到'把苦难当考验'，这本书是《活法》《干法》之后，最接近'总纲'的一本。"},
    "meta": [["书名", "心法 / 心"], ["作者", "稻盛和夫（1932—2022）"], ["身份", "京瓷 · KDDI 创始人"], ["首版", "2019（87 岁收官）"], ["领域", "心性哲学"], ["关键词", "心相 · 利他之心 · 感恩 · 反省 · 总纲"]],
    "thesis": "稻盛晚年把一切归因于一个字：<b>心</b>。'人生的一切，都是自己内心的投射'——你抱着怎样的心相去活，世界就以怎样的样子回敬你。相较《活法》的'作为人何谓正确'、《干法》的'工作即修行'，这本《心》是更直接的总纲：把对世界的态度，先安顿好。",
    "chips": ["#心相", "#利他之心", "#感恩之心", "#反省之心", "#心即理", "#人生投射", "#收官之作", "#总纲"],
    "oneliner": "人生的一切，<br/>都是自己<br/>内心的<br/>投射。",
    "onelinerSrc": "— 心相",
    "oneHead": {"num": "02 /", "eyebrow": "ONE SENTENCE", "h2": "一句话总览", "sub": ""},
    "dualHead": {"num": "03 /", "eyebrow": "THE CORE CONTRASTS", "h2": "两组核心对照<b class=\"tail\">·</b>思维方式与赌注", "sub": "全书真正的骨架是两组张力：一组在\"如何看待企业 / 工作\"上，一组在\"如何对待人 / 技术\"上。把这两个对照想清楚，整本书的骨架就立住了。"},
    "dual": [{"label": "A · 解题方向：向外求，还是向内求？", "a": {"tag": "OUTWARD", "title": "向外求", "en": "（（怪环境 / 运气））", "sub": "", "p": "遇到坏事先怪环境、怪运气、怪别人。省事，但把钥匙交了出去，自己永远改不了处境。", "ul": [["归因", "外部"], ["掌控", "弱"], ["后果", "反复受困"]], "q": "\"“是环境 / 运气不好。”\""}, "b": {"tag": "INWARD", "title": "向内求", "en": "（（修心相））", "sub": "", "p": "稻盛主张人生是内心的投射。遇到事先问'我的心相在投射什么'，把钥匙拿回自己手里。", "ul": [["归因", "内心"], ["掌控", "强"], ["后果", "可改变"]], "q": "\"“人生的一切，都是内心的投射。”\""}}, {"label": "B · 心的方向：利己，还是利他？", "a": {"tag": "SELFISH", "title": "利己之心", "en": "（（先顾自己））", "sub": "", "p": "凡事先为自己打算，短期得利，但关系与信任稀薄，路越走越窄。", "ul": [["起点", "自我"], ["关系", "薄"], ["上限", "窄"]], "q": "\"“人不为己天诛地灭。”\""}, "b": {"tag": "ALTruIST", "title": "利他之心", "en": "（（先利他））", "sub": "", "p": "利他之心是宇宙间最朴素也最强大的力量。先为他人着想，反而打开局面、聚起人与运。", "ul": [["起点", "他人"], ["关系", "厚"], ["上限", "宽"]], "q": "\"“利他之心，最强大。”\""}}],
    "biasHead": {"num": "04 /", "eyebrow": "KEY CONCEPTS", "h2": "十张<b class=\"tail\">书签</b>，拆开这套打法", "sub": "前五张讲\"他怎么想、怎么做\"，中间三张讲\"他怎么带人 / 看世界\"，最后两张讲这套哲学的另一面——少了后面两张，就只剩口号。"},
    "concepts": [{"num": "N° 01", "title": "心相", "en": "Mindscape", "mech": "人生的一切是内心的投射。你抱怎样的心相，世界就怎样回敬你。改命先改心。", "example": "例：遇到坏事，先问'我的心相在投射什么'再反应。"}, {"num": "N° 02", "title": "利他之心", "en": "Altruistic Mind", "mech": "利他不是牺牲，而是宇宙间最朴素也最强大的力量。先利他，反而聚起人与运。", "example": "例：本周做一次'利他优先'的选择并记录结果。"}, {"num": "N° 03", "title": "感恩之心", "en": "Gratitude", "mech": "感恩是把好运接住的手势。常怀感恩，心就敞亮，机会也愿意靠近。", "example": "例：每天一句感恩，哪怕只是'今天还活着'。"}, {"num": "N° 04", "title": "反省之心", "en": "Reflection", "mech": "每日一次反省，胜过一年一次后悔。反省把'干'沉淀成心性的养分。", "example": "例：设一个每日一分钟的'反省'功课。"}, {"num": "N° 05", "title": "把心磨亮", "en": "Polish the Mind", "mech": "心像镜子，要勤擦。日省、利他、感恩，都是磨心的方式。", "example": "例：用'利他 + 感恩 + 反省'三步，给心做一次清洁。"}, {"num": "N° 06", "title": "人生即心相的回响", "en": "Echo", "mech": "你发出怎样的心，世界就回怎样的声。心定，则外境不乱。", "example": "例：在冲突前先静三秒，让'心定'再决定。"}, {"num": "N° 07", "title": "接纳与转念", "en": "Accept & Reframe", "mech": "把困境转念成'考验'，把失去转念成'腾出'。转念，是心的自由。", "example": "例：把一次抱怨，改写成'我能改变什么'。"}, {"num": "N° 08", "title": "善意的循环", "en": "Kindness Loop", "mech": "一个善意会引来下一个善意。你释放的，最终绕回自己。", "example": "例：在团队里发起一次'善意循环'的小实验。"}, {"num": "N° 09", "title": "心定则事定", "en": "Calm Mind, Steady Work", "mech": "外境纷乱时，先把心定住。心定，判断才不偏，事才稳。", "example": "例：重大决定前，给自己一段'先静'的时间。"}, {"num": "N° 10", "title": "收官之'心'", "en": "The Final Mind", "mech": "这是稻盛 87 岁的总结：把一生收束到'心'。读它，是读一份总纲而非新论。", "example": "例：给晚年 / 长期，写一句你想被记住的'心'。"}],
    "mapHead": {"num": "05 /", "eyebrow": "CHAPTER MAP", "h2": "全书<b class='tail'>五章</b> · 心性脉络", "sub": "晚年的稻盛把一切收束到'心'：利他最强大、感恩与反省是日课、心相决定世界如何回敬你。"},
    "chapters": [{"pin": "一", "title": "为什么是'心'", "range": "缘起", "items": ["八十年后的总收束", "一切回到一个字", "心是命运的开关"]}, {"pin": "二", "title": "利他之心：最强大的驱动", "range": "利他", "items": ["利他最朴素也最强大", "利他即利己", "先给出去"]}, {"pin": "三", "title": "感恩与反省：每日的功课", "range": "日课", "items": ["把心性拆成两道日常", "晨省与夜省", "感恩先于要求"]}, {"pin": "四", "title": "心相的投射：世界如何回敬你", "range": "投射", "items": ["发出怎样的心", "收到怎样的声", "境由心造"]}, {"pin": "五", "title": "把一颗心，安顿好", "range": "安顿", "items": ["从个人到总纲", "如何把心安放", "一生修一颗心"]}],
    "quotesHead": {"num": "06 /", "eyebrow": "QUOTES", "h2": "五句值得抄在笔记本上的话", "sub": "以下为书中观点与原文的中文转述，尽量保留原意，未逐字照搬。"},
    "quotes": [{"text": "人生的一切，<br/>都是自己内心的投射。", "src": "— 心相"}, {"text": "利他之心，<br/>是宇宙间最朴素也最强大的力量。", "src": "— 利他"}, {"text": "感恩，是把好运<br/>接住的手势。", "src": "— 感恩"}, {"text": "每天一次反省，<br/>胜过一年一次后悔。", "src": "— 反省"}, {"text": "把心磨亮，<br/>路自然就亮了。", "src": "— 磨心"}],
